import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.Dq6wn6bv.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"docs/roadmap.md","filePath":"docs/roadmap.md"}'),o={name:"docs/roadmap.md"};function h(n,e,i,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>What ships and in which order. A <strong>phase</strong> is a layer of the product (<a href="./architecture#delivery-phases">architecture</a>); a <strong>release</strong> is a set of features inside a phase that makes sense together, cut when it is ready, not on a date.</p><blockquote><p><strong>Proposal.</strong> The grouping below is a draft for the maintainer to approve in <a href="https://github.com/tkint/coach-poulpy/issues/229" target="_blank" rel="noreferrer">#229</a>. Version numbers and release names are not final, and the GitHub milestones still follow the phases until it is decided. The current version is the latest tag on the <a href="https://github.com/tkint/coach-poulpy/releases" target="_blank" rel="noreferrer">Releases</a> page.</p></blockquote><h2 id="phase-1-·-guest-app" tabindex="-1">Phase 1 · Guest app <a class="header-anchor" href="#phase-1-·-guest-app" aria-label="Permalink to &quot;Phase 1 · Guest app&quot;">​</a></h2><p>Everything on the phone, no account. Phase 1 is done when the app is complete on both platforms: <strong>1.0</strong>.</p><table tabindex="0"><thead><tr><th>Release</th><th>Theme</th><th>Issues</th></tr></thead><tbody><tr><td>0.6</td><td>Easier to read and use</td><td><a href="https://github.com/tkint/coach-poulpy/issues/222" target="_blank" rel="noreferrer">#222</a> smaller Home cards, <a href="https://github.com/tkint/coach-poulpy/issues/223" target="_blank" rel="noreferrer">#223</a> exercise details in the session recap, <a href="https://github.com/tkint/coach-poulpy/issues/221" target="_blank" rel="noreferrer">#221</a> back from devices, <a href="https://github.com/tkint/coach-poulpy/issues/220" target="_blank" rel="noreferrer">#220</a> a clearer pause button</td></tr><tr><td>0.7</td><td>Reuse and share workouts</td><td><a href="https://github.com/tkint/coach-poulpy/issues/224" target="_blank" rel="noreferrer">#224</a> a workout from any session, <a href="https://github.com/tkint/coach-poulpy/issues/152" target="_blank" rel="noreferrer">#152</a> details before importing, <a href="https://github.com/tkint/coach-poulpy/issues/37" target="_blank" rel="noreferrer">#37</a> and <a href="https://github.com/tkint/coach-poulpy/issues/38" target="_blank" rel="noreferrer">#38</a> swap an exercise for a variation</td></tr><tr><td>0.8</td><td>Training plans</td><td><a href="https://github.com/tkint/coach-poulpy/issues/17" target="_blank" rel="noreferrer">#17</a> follow a plan</td></tr><tr><td>0.9</td><td>Beyond the app</td><td><a href="https://github.com/tkint/coach-poulpy/issues/22" target="_blank" rel="noreferrer">#22</a> FIT export, <a href="https://github.com/tkint/coach-poulpy/issues/23" target="_blank" rel="noreferrer">#23</a> Apple Health and Health Connect, <a href="https://github.com/tkint/coach-poulpy/issues/177" target="_blank" rel="noreferrer">#177</a> app icon, <a href="https://github.com/tkint/coach-poulpy/issues/24" target="_blank" rel="noreferrer">#24</a> TestFlight</td></tr><tr><td>1.0</td><td>Phase 1 complete</td><td>Whatever remains, then the stores</td></tr></tbody></table><h2 id="phase-2-·-treadmill" tabindex="-1">Phase 2 · Treadmill <a class="header-anchor" href="#phase-2-·-treadmill" aria-label="Permalink to &quot;Phase 2 · Treadmill&quot;">​</a></h2><p>Runs alongside phase 1, because the treadmill link was the riskiest piece. Releases are cut with the phase 1 release they fall in.</p><table tabindex="0"><thead><tr><th>Theme</th><th>Issues</th></tr></thead><tbody><tr><td>Live and the player work as one</td><td><a href="https://github.com/tkint/coach-poulpy/issues/225" target="_blank" rel="noreferrer">#225</a> how much of the player Live shares (<a href="./adr/0018-live-plays-mixed-workouts-with-the-players-steps">ADR 0018</a>), <a href="https://github.com/tkint/coach-poulpy/issues/14" target="_blank" rel="noreferrer">#14</a> choose what a device measures</td></tr></tbody></table><h2 id="phase-3-·-accounts-and-sync" tabindex="-1">Phase 3 · Accounts and sync <a class="header-anchor" href="#phase-3-·-accounts-and-sync" aria-label="Permalink to &quot;Phase 3 · Accounts and sync&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Theme</th><th>Issues</th></tr></thead><tbody><tr><td>A server to host</td><td><a href="https://github.com/tkint/coach-poulpy/issues/28" target="_blank" rel="noreferrer">#28</a> hosting provider, <a href="https://github.com/tkint/coach-poulpy/issues/27" target="_blank" rel="noreferrer">#27</a> catalog updates on launch</td></tr><tr><td>Accounts</td><td><a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a> accounts and sync between phones, <a href="https://github.com/tkint/coach-poulpy/issues/26" target="_blank" rel="noreferrer">#26</a> admin menu</td></tr></tbody></table><h2 id="phase-4-·-website" tabindex="-1">Phase 4 · Website <a class="header-anchor" href="#phase-4-·-website" aria-label="Permalink to &quot;Phase 4 · Website&quot;">​</a></h2><p><a href="https://github.com/tkint/coach-poulpy/issues/29" target="_blank" rel="noreferrer">#29</a> run the shared engine in the browser with Kotlin/JS, then plan, review and run guided sessions.</p><h2 id="phase-5-·-sharing-and-coaching" tabindex="-1">Phase 5 · Sharing and coaching <a class="header-anchor" href="#phase-5-·-sharing-and-coaching" aria-label="Permalink to &quot;Phase 5 · Sharing and coaching&quot;">​</a></h2><p>Library sync or copy, coach links and comments. Not broken into issues yet.</p><h2 id="later" tabindex="-1">Later <a class="header-anchor" href="#later" aria-label="Permalink to &quot;Later&quot;">​</a></h2><p>Wanted, not planned: <a href="https://github.com/tkint/coach-poulpy/issues/30" target="_blank" rel="noreferrer">#30</a> control the treadmill, <a href="https://github.com/tkint/coach-poulpy/issues/31" target="_blank" rel="noreferrer">#31</a> heart rate straps, <a href="https://github.com/tkint/coach-poulpy/issues/32" target="_blank" rel="noreferrer">#32</a> user-created exercises, <a href="https://github.com/tkint/coach-poulpy/issues/33" target="_blank" rel="noreferrer">#33</a> progression rules, <a href="https://github.com/tkint/coach-poulpy/issues/75" target="_blank" rel="noreferrer">#75</a> guided building of a long run, <a href="https://github.com/tkint/coach-poulpy/issues/124" target="_blank" rel="noreferrer">#124</a> Poulpy&#39;s coaching style, <a href="https://github.com/tkint/coach-poulpy/issues/228" target="_blank" rel="noreferrer">#228</a> APIs and an MCP server.</p><h2 id="not-tied-to-a-release" tabindex="-1">Not tied to a release <a class="header-anchor" href="#not-tied-to-a-release" aria-label="Permalink to &quot;Not tied to a release&quot;">​</a></h2><p>Documentation work (<a href="https://github.com/tkint/coach-poulpy/issues/226" target="_blank" rel="noreferrer">#226</a> diagrams, <a href="https://github.com/tkint/coach-poulpy/issues/227" target="_blank" rel="noreferrer">#227</a> readability) and <a href="https://github.com/tkint/coach-poulpy/issues/229" target="_blank" rel="noreferrer">#229</a>, which defines how releases are planned, go in whichever release is open.</p>',19)])])}const b=t(o,[["render",h]]);export{u as __pageData,b as default};
